        's_whose_narrows' => 'നാല് കാർഡുകൾ ചുരുങ്ങുന്നു: <strong>Tickets</strong>, <strong>Tasks</strong>, <strong>Changes</strong>, <strong>Morning Checks</strong>. അവയിലെ ഓരോ കണക്കും ടോഗിളിനെ പിന്തുടരുന്നു &mdash; നില പ്രകാരം നിങ്ങളുടെ തുറന്ന ടിക്കറ്റുകൾ, കാലാവധി കഴിഞ്ഞ നിങ്ങളുടെ ടാസ്കുകൾ, നിങ്ങൾക്ക് നിയോഗിച്ച മാറ്റങ്ങൾ.',
        's_whose_impersonal' => '<strong>ആറ് കാർഡുകൾ ചുരുങ്ങില്ല, അവയെ <em>everyone</em> എന്ന് ലേബൽ ചെയ്തിരിക്കുന്നു, അതിനാൽ ഒരു ടീം-വൈഡ് കണക്ക് നിങ്ങൾ ഒരിക്കലും വ്യക്തിപരമായ ഒന്നായി വായിക്കില്ല.</strong> ഒരു മോശമായ സേവനവും പരാജയപ്പെട്ട ഒരു വർക്ക്ഫ്ലോയും ആർക്കും അവകാശപ്പെട്ടതല്ല. ഉപകരണങ്ങൾ അനലിസ്റ്റുകൾക്കല്ല, <em>end users</em>-നാണ് നിയോഗിക്കുന്നത്, അതിനാൽ &ldquo;my equipment&rdquo; മിക്കവർക്കും ശൂന്യമായിരിക്കും. Calendar കാർഡ് പങ്കിട്ട ടീം കലണ്ടറാണ്. Contracts, Knowledge എന്നിവ ഒരു ഉടമയെ രേഖപ്പെടുത്തുന്നു, പക്ഷേ കാലാവധി കഴിയാൻ പോകുന്ന ഒരു കരാർ ആരാണ് ഉടമ എന്നത് പരിഗണിക്കാതെ പിന്തുടരേണ്ടതുണ്ട്, കാലാവധി കഴിഞ്ഞ അവലോകനമുള്ള ഒരു ലേഖനം ഒരാളുടെ ജോലിഭാരത്തിലെ വിടവല്ല, ലൈബ്രറിയിലെ വിടവാണ്.',
        's_whose_unassigned' => '<strong>നിയോഗിക്കാത്ത ടിക്കറ്റുകൾ</strong> ഒരു ക്രമീകരണത്തിലും ചുരുങ്ങില്ല. നിർവചനപ്രകാരം ഒരു നിയോഗിക്കാത്ത ടിക്കറ്റ് നിങ്ങളുടേതല്ല, അതിനാൽ &ldquo;mine&rdquo; എപ്പോഴും പൂജ്യം കാണിക്കും &mdash; അവിടെ പൂജ്യം <em>ക്യൂ ശൂന്യമാണ്</em> എന്ന് വായിക്കപ്പെടും, ഒരു അവകാശപ്പെടാത്ത കൂമ്പാരം അർത്ഥമാക്കുന്നതിന്റെ നേർവിപരീതമാണിത്.',
        's_whose_checks' => '<strong>മോർണിംഗ് ചെക്കുകൾ അവയുടെ ഗ്രൂപ്പിലൂടെയാണ് പൊരുത്തപ്പെടുത്തുന്നത്.</strong> ഒരു ചെക്ക് ഒരു ഗ്രൂപ്പിൽ ഇട്ട് ആ ഗ്രൂപ്പിനെ ഒരു ടീമിലേക്കോ വ്യക്തിയിലേക്കോ ചൂണ്ടിച്ച് റൂട്ട് ചെയ്യുന്നു, അതിനാൽ <em>mine</em> എന്നാൽ നിങ്ങൾക്ക് നിയോഗിച്ച ചെക്കുകൾ, നിങ്ങളിലേക്ക് ചൂണ്ടിച്ച ഒരു ഗ്രൂപ്പിലെ ചെക്കുകൾ, അല്ലെങ്കിൽ നിങ്ങൾ ഉൾപ്പെടുന്ന ഒരു ടീമിലേക്ക് ചൂണ്ടിച്ച ഒരു ഗ്രൂപ്പിലെ ചെക്കുകൾ എന്നാണ്.',
        's_whose_setting' => 'നിങ്ങൾ <strong>Mine</strong>-ൽ ആയിരിക്കുമ്പോൾ ആ ആറ് കാർഡുകൾക്ക് എന്ത് സംഭവിക്കുന്നു എന്നത് <strong>Preferences &rarr; General</strong>-ന് കീഴിൽ നിങ്ങളുടെ സ്വന്തം തിരഞ്ഞെടുപ്പാണ്: അവ കാണിക്കുന്നത് തുടരുക, അല്ലെങ്കിൽ കൃത്യമായ വ്യക്തിഗത ബോർഡിനായി അവ മറയ്ക്കുക. അവ സ്ഥിരസ്ഥിതിയായി നിലനിർത്തുന്നു, കാരണം നിങ്ങൾ സ്വന്തം ജോലിയിലേക്ക് മാറിയതുകൊണ്ട് അപ്രത്യക്ഷമാകേണ്ട അവസാനത്തെ കാര്യമാണ് ഒരു മോശമായ സേവനം.',
        'nav_cards' => 'മൊഡ്യൂൾ കാർഡുകൾ വിശദീകരിച്ചു',
        'nav_refresh' => 'സ്വയം പുതുക്കൽ',
        'nav_tips' => 'ദ്രുത നുറുങ്ങുകൾ',
        'nav_settings' => 'ക്രമീകരണങ്ങൾ',
        's1_title' => 'അവലോകനം',
        's1_intro' => 'വാച്ച്‌ടവർ നിങ്ങളുടെ IT പ്രവർത്തനങ്ങൾക്കായുള്ള ഏക സിംഗിൾ പെയ്ൻ ഓഫ് ഗ്ലാസ് ആണ്. അടിയന്തര ഇനങ്ങൾ പരിശോധിക്കാൻ ഓരോ മൊഡ്യൂളും വെവ്വേറെ തുറക്കുന്നതിന് പകരം, ഓരോ മൊഡ്യൂളിൽ നിന്നുമുള്ള ഏറ്റവും പ്രധാന വിവരങ്ങൾ വാച്ച്‌ടവർ ഒറ്റ ഡാഷ്‌ബോർഡിലേക്ക് കൊണ്ടുവരുന്നു. ഒറ്റനോട്ടത്തിൽ, എന്തിന് ശ്രദ്ധ ആവശ്യമാണ്, എന്ത് സുഗമമായി പ്രവർത്തിക്കുന്നു, എവിടെ ശ്രദ്ധ കേന്ദ്രീകരിക്കണം എന്നൊക്കെ കാണാം.',
        's1_feat1_title' => 'ശ്രദ്ധാ ബോർഡ്',
        's1_feat1_desc' => 'എല്ലാ മൊഡ്യൂളുകളിലുമായി നിങ്ങളുടെ ശ്രദ്ധ ആവശ്യമുള്ളവ ഒരിടത്ത് കാണുക. പ്രഭാത പരിശോധനകൾ, ടിക്കറ്റുകൾ, മാറ്റങ്ങൾ, കലണ്ടർ ഇവന്റുകൾ, സേവന നില, കരാറുകൾ, അറിവ് ലേഖനങ്ങൾ, ആസ്തികൾ എന്നിവയെല്ലാം ഒറ്റ സ്ക്രീനിൽ സംഗ്രഹിച്ചിരിക്കുന്നു.',
        's1_feat2_title' => 'നിറം-കോഡ് ചെയ്ത നില',
        's1_feat2_desc' => 'തൽക്ഷണ ട്രയാജിനായി ഓരോ മൊഡ്യൂൾ കാർഡും പച്ച, മഞ്ഞ, അല്ലെങ്കിൽ ചുവപ്പ് സ്റ്റാറ്റസ് ഡോട്ട് പ്രദർശിപ്പിക്കുന്നു. ഏതൊക്കെ മേഖലകൾ ആരോഗ്യകരമാണ്, ഏതിന് ശ്രദ്ധ വേണം, ഏതിന് ഉടനടി നടപടി വേണം എന്ന് ഒറ്റനോട്ടത്തിൽ പറയാം.',
        's1_feat3_title' => 'സ്വയം പുതുക്കൽ',
        's1_feat3_desc' => 'ഡാഷ്‌ബോർഡ് ഓരോ 5 മിനിറ്റിലും സ്വയം പുതുക്കുന്നു, അതിനാൽ ഒരു മാനുവൽ നടപടിയും കൂടാതെ വിവരങ്ങൾ കാലികമായി തുടരുന്നു. വാച്ച്‌ടവർ തുറന്നുവെച്ചാൽ അത് പശ്ചാത്തലത്തിൽ സ്വയം കാലികമായി നിലനിർത്തുന്നു.',
        's1_feat4_title' => 'ക്ലിക്ക്-ത്രൂ',
        's1_feat4_desc' => 'ഓരോ കാർഡിൽ നിന്നും ഏത് മൊഡ്യൂളിലേക്കും നേരിട്ട് കടക്കുക. ഓരോ മൊഡ്യൂൾ പേരും ക്ലിക്ക് ചെയ്യാവുന്ന ലിങ്കാണ്, അത് നിങ്ങളെ നേരെ പ്രസക്ത മേഖലയിലേക്ക് കൊണ്ടുപോകുന്നു, അതിനാൽ ശരിയായ പേജ് തിരയാതെ പ്രശ്നങ്ങളിൽ നടപടിയെടുക്കാം.',
        's2_title' => 'ഡാഷ്‌ബോർഡ് ലേഔട്ട്',
        's2_p1' => 'വാച്ച്‌ടവർ ഡാഷ്‌ബോർഡ് മൊഡ്യൂൾ കാർഡുകളുടെ പ്രതികരണാത്മക 3-കോളം ഗ്രിഡ് ഉപയോഗിക്കുന്നു. ചെറിയ സ്ക്രീനുകളിൽ ഗ്രിഡ് 2 കോളമോ ഒറ്റ കോളമോ ആയി ക്രമീകരിക്കുന്നു, അതിനാൽ ഇത് ഏത് ഉപകരണത്തിലും പ്രവർത്തിക്കുന്നു. ഗ്രിഡിന് മുകളിൽ പുതുക്കൽ ബട്ടണും ഡാറ്റ അവസാനമായി എപ്പോൾ എടുത്തുവെന്ന് കാണിക്കുന്ന "പുതുക്കി" ടൈംസ്റ്റാമ്പും ഉള്ള ടൈറ്റിൽ ബാർ ഉണ്ട്.',
        's2_p2' => 'ഗ്രിഡിലെ ഓരോ കാർഡും ഒരു സ്ഥിരമായ ഘടന പിന്തുടരുന്നു, അതിനാൽ നിങ്ങൾക്ക് അവ വേഗത്തിൽ സ്കാൻ ചെയ്യാം:',
        's2_diagram_name' => 'മൊഡ്യൂൾ പേര്',
        's2_diagram_open' => 'തുറന്നവ',
        's2_diagram_active' => 'സജീവം',
        's2_diagram_hold' => 'തടഞ്ഞുവച്ചവ',
        's2_diagram_clear' => 'എല്ലാം വ്യക്തം — അടിയന്തര ഇനങ്ങളൊന്നുമില്ല',
        's2_field_icon' => '<strong>നിറമുള്ള ഐക്കൺ</strong> &mdash; മൊഡ്യൂളിന്റെ തീം നിറത്തിലുള്ള ഒരു ചെറിയ ചതുര ഐക്കൺ (പ്രഭാത പരിശോധനകൾക്ക് ടീൽ, ടിക്കറ്റുകൾക്ക് നീല, മുതലായവ) അതിനാൽ ഓരോ കാർഡും തൽക്ഷണം തിരിച്ചറിയാം.',
        's2_field_name' => '<strong>മൊഡ്യൂൾ പേര്</strong> &mdash; ആ മൊഡ്യൂളിലേക്ക് നേരിട്ട് നാവിഗേറ്റ് ചെയ്യുന്ന ക്ലിക്ക് ചെയ്യാവുന്ന ലിങ്ക്. നേരെ കടന്ന് നടപടിയെടുക്കാൻ ക്ലിക്ക് ചെയ്യുക.',
        's2_field_dot' => '<strong>സ്റ്റാറ്റസ് ഡോട്ട്</strong> &mdash; ആ മൊഡ്യൂളിന്റെ മൊത്തത്തിലുള്ള അടിയന്തരാവസ്ഥ കാണിക്കുന്ന മുകളിൽ-വലത് കോണിലെ പച്ച, മഞ്ഞ, അല്ലെങ്കിൽ ചുവപ്പ് ഡോട്ട്.',
        's2_field_metrics' => '<strong>പ്രധാന മെട്രിക്കുകൾ</strong> &mdash; ഏറ്റവും പ്രധാന എണ്ണങ്ങൾ സംഗ്രഹിക്കുന്ന വലിയ സംഖ്യകൾ (ഉദാ. തുറന്ന ടിക്കറ്റുകൾ, പൂർത്തിയാക്കിയ പരിശോധനകൾ, കാലഹരണപ്പെടുന്ന കരാറുകൾ).',
        's2_field_attention' => '<strong>ശ്രദ്ധാ ഇനങ്ങൾ</strong> &mdash; ആ മൊഡ്യൂളിനുള്ളിൽ പ്രത്യേകമായി എന്തിന് ശ്രദ്ധ വേണമെന്ന് എടുത്തുകാണിക്കുന്ന നിറം-കോഡ് ചെയ്ത സന്ദേശ വരികൾ.',
        's2_tip' => 'കാർഡ് ലേഔട്ട് സ്കാനിംഗിനായാണ് രൂപകൽപ്പന ചെയ്തിരിക്കുന്നത്, ആഴത്തിലുള്ള വിശകലനത്തിനല്ല. ഏതൊക്കെ മൊഡ്യൂളുകൾക്ക് നിങ്ങളുടെ ശ്രദ്ധ വേണമെന്ന് തിരിച്ചറിയാൻ വാച്ച്‌ടവർ ഉപയോഗിക്കുക, തുടർന്ന് മുഴുവൻ വിശദാംശങ്ങൾക്കായി മൊഡ്യൂളിലേക്ക് തന്നെ ക്ലിക്ക് ചെയ്യുക.',
        's3_title' => 'സ്റ്റാറ്റസ് ഡോട്ടുകൾ മനസ്സിലാക്കൽ',
        's3_intro' => 'ഓരോ മൊഡ്യൂൾ കാർഡും അതിന്റെ ഹെഡറിൽ ഒരു സ്റ്റാറ്റസ് ഡോട്ട് പ്രദർശിപ്പിക്കുന്നു. നിങ്ങളുടെ IT പ്രവർത്തനങ്ങളുടെ ആ മേഖലയ്ക്ക് ശ്രദ്ധ ആവശ്യമുണ്ടോ എന്നതിന്റെ തൽക്ഷണ ദൃശ്യ സൂചകം ഈ ഡോട്ട് നൽകുന്നു. ഓരോ മൊഡ്യൂളിൽ നിന്നും ലഭിക്കുന്ന ഡാറ്റയെ അടിസ്ഥാനമാക്കി നിറം സ്വയം നിർണ്ണയിക്കപ്പെടുന്നു.',
        's3_green_label' => 'പച്ച',
        's3_green_desc' => 'എല്ലാം ശരിയാണ്. നടപടി ആവശ്യമില്ല. ശ്രദ്ധ ആവശ്യമുള്ള തീർപ്പാക്കാത്ത പ്രശ്നങ്ങളോ ഇനങ്ങളോ ഇല്ലാതെ മൊഡ്യൂൾ ആരോഗ്യകരമായ അവസ്ഥയിലാണ്.',
        's3_green_examples' => '<strong>ഉദാഹരണങ്ങൾ:</strong> എല്ലാ പ്രഭാത പരിശോധനകളും വിജയിച്ചു, അടിയന്തര ടിക്കറ്റുകളൊന്നുമില്ല, എല്ലാ സിസ്റ്റങ്ങളും പ്രവർത്തനക്ഷമം, ഉടൻ കാലഹരണപ്പെടുന്ന കരാറുകളൊന്നുമില്ല.',
        's3_amber_label' => 'മഞ്ഞ',
        's3_amber_desc' => 'എന്തെങ്കിലും ശ്രദ്ധ ആവശ്യമാണ്, പക്ഷേ ഗുരുതരമല്ല. അവസരം ലഭിക്കുമ്പോൾ നിങ്ങൾ അവലോകനം ചെയ്യേണ്ട ഇനങ്ങളുണ്ട്, പക്ഷേ ഒന്നും അടിയന്തരമല്ല.',
        's3_amber_examples' => '<strong>ഉദാഹരണങ്ങൾ:</strong> മുന്നറിയിപ്പുകളുള്ള പരിശോധനകൾ, ഏൽപ്പിക്കാത്ത ടിക്കറ്റുകൾ, അംഗീകാരത്തിനായി കാത്തിരിക്കുന്ന മാറ്റങ്ങൾ, 90 ദിവസത്തിനുള്ളിൽ കാലഹരണപ്പെടുന്ന കരാറുകൾ.',
        's3_red_label' => 'ചുവപ്പ്',
        's3_red_desc' => 'അടിയന്തര ഇനങ്ങൾക്ക് ഉടനടി നടപടി ആവശ്യമാണ്. എന്തെങ്കിലും പരാജയപ്പെട്ടു, കാലാവധി കഴിഞ്ഞു, അല്ലെങ്കിൽ ഗുരുതരമായി ബാധിക്കപ്പെട്ടു, ഉടൻ പരിഹരിക്കേണ്ടതുണ്ട്.',
        's3_red_examples' => '<strong>ഉദാഹരണങ്ങൾ:</strong> പ്രഭാത പരിശോധനകൾ ആരംഭിച്ചിട്ടില്ല അല്ലെങ്കിൽ പരാജയപ്പെട്ടു, അടിയന്തര/ഉയർന്ന മുൻഗണനയുള്ള ടിക്കറ്റുകൾ, വലിയ സേവന തടസ്സങ്ങൾ, 30 ദിവസത്തിനുള്ളിൽ കാലഹരണപ്പെടുന്ന കരാറുകൾ.',
        's3_tip' => 'ഡോട്ടുകളെ ഒരു ട്രാഫിക് ലൈറ്റ് പോലെ കരുതുക. പച്ച എന്നാൽ നിങ്ങളുടെ ദിവസവുമായി മുന്നോട്ട്, മഞ്ഞ എന്നാൽ കഴിയുമ്പോൾ അവലോകനം ചെയ്യുക, ചുവപ്പ് എന്നാൽ ചെയ്യുന്നത് നിർത്തി അന്വേഷിക്കുക. എല്ലാ ഡോട്ടുകളും പച്ചയായി നിലനിർത്തുകയാണ് ലക്ഷ്യം.',
        's4_title' => 'മൊഡ്യൂൾ കാർഡുകൾ വിശദീകരിച്ചു',
        's4_intro' => 'വാച്ച്‌ടവർ എട്ട് മൊഡ്യൂളുകൾ നിരീക്ഷിക്കുന്നു. ഓരോ കാർഡും ആ മേഖലയ്ക്ക് ഏറ്റവും പ്രസക്തമായ വിവരങ്ങൾ കാണിക്കാൻ ക്രമീകരിച്ചിരിക്കുന്നു. ഓരോ കാർഡും എന്ത് പ്രദർശിപ്പിക്കുന്നുവെന്നും അതിന്റെ സ്റ്റാറ്റസ് ഡോട്ട് നിറം എന്ത് ട്രിഗർ ചെയ്യുന്നുവെന്നും ഇതാ.',
        's4_mc_title' => 'പ്രഭാത പരിശോധനകൾ',
        's4_mc_desc' => 'പൂർത്തീകരണ പുരോഗതി (ഉദാ. 8/10 പൂർത്തിയായി) കൂടാതെ ശരി, മുന്നറിയിപ്പ്, പരാജയം ഫലങ്ങളുടെ എണ്ണവും കാണിക്കുന്നു. പരിശോധനകൾ ആരംഭിച്ചിട്ടില്ലെങ്കിലോ ഏതെങ്കിലും പരാജയപ്പെട്ടാലോ ശ്രദ്ധാ ഇനങ്ങൾ അടയാളപ്പെടുത്തുന്നു.',
        's4_mc_triggers' => '<strong>ചുവപ്പ്:</strong> ഇന്ന് പരിശോധനകൾ ആരംഭിച്ചിട്ടില്ല, അല്ലെങ്കിൽ ഏതെങ്കിലും പരിശോധനകൾ പരാജയപ്പെട്ടു. <strong>മഞ്ഞ:</strong> പരിശോധനകൾ അപൂർണ്ണം അല്ലെങ്കിൽ മുന്നറിയിപ്പുകൾ ഉണ്ട്. <strong>പച്ച:</strong> എല്ലാ പരിശോധനകളും പൂർത്തിയായി, വിജയിച്ചു.',
        's4_tk_title' => 'ടിക്കറ്റുകൾ',
        's4_tk_desc' => 'പുതിയവ, സജീവം, തടഞ്ഞുവച്ചവ എന്നിങ്ങനെ വിഭജിച്ച മൊത്തം തുറന്ന എണ്ണം പ്രദർശിപ്പിക്കുന്നു. അടിയന്തര/ഉയർന്ന മുൻഗണനയുള്ള ടിക്കറ്റുകളും ഏൽപ്പിക്കാത്തവയും ശ്രദ്ധാ ഇനങ്ങൾ എടുത്തുകാണിക്കുന്നു.',
        's4_tk_triggers' => '<strong>ചുവപ്പ്:</strong> അടിയന്തര അല്ലെങ്കിൽ ഉയർന്ന മുൻഗണനയുള്ള ടിക്കറ്റുകൾ ഉണ്ട്. <strong>മഞ്ഞ:</strong> ഏൽപ്പിക്കാത്ത ടിക്കറ്റുകൾ ഉണ്ട്. <strong>പച്ച:</strong> അടിയന്തര ഇനങ്ങളോ ഏൽപ്പിക്കാത്ത ടിക്കറ്റുകളോ ഇല്ല.',
        's4_ch_title' => 'മാറ്റങ്ങൾ',
        's4_ch_desc' => 'അടുത്ത 7 ദിവസത്തിൽ ഷെഡ്യൂൾ ചെയ്ത മാറ്റങ്ങളുടെ എണ്ണം, ഇപ്പോൾ എത്ര പുരോഗമിക്കുന്നു, എത്ര അംഗീകാരത്തിന് തീർപ്പാക്കാത്തവ എന്നിവ കാണിക്കുന്നു. അംഗീകരിക്കാത്തതും സജീവവുമായ മാറ്റങ്ങൾ ശ്രദ്ധാ ഇനങ്ങൾ ചൂണ്ടിക്കാണിക്കുന്നു.',
        's4_ch_triggers' => '<strong>മഞ്ഞ:</strong> അംഗീകാരത്തിനായി കാത്തിരിക്കുന്ന മാറ്റങ്ങൾ. <strong>പച്ച:</strong> അംഗീകരിക്കാത്ത മാറ്റങ്ങളൊന്നുമില്ല.',
        's4_cal_title' => 'കലണ്ടർ',
        's4_cal_desc' => 'ഇന്നും ഈ ആഴ്ചയിലുമുള്ള ഇവന്റുകളുടെ എണ്ണം പ്രദർശിപ്പിക്കുന്നു. ഇന്ന് ഇവന്റുകൾ ഉണ്ടെങ്കിൽ, അവ അവയുടെ സമയങ്ങളോടെ (അല്ലെങ്കിൽ ദിവസം മുഴുവൻ ഇവന്റുകൾക്ക് "ദിവസം മുഴുവൻ") പട്ടികപ്പെടുത്തുന്നു.',
        's4_cal_triggers' => '<strong>മഞ്ഞ:</strong> ഇന്നത്തേക്ക് ഷെഡ്യൂൾ ചെയ്ത ഇവന്റുകൾ. <strong>പച്ച:</strong> ഇന്ന് ഇവന്റുകളൊന്നുമില്ല.',
        's4_ss_title' => 'സേവന നില',
        's4_ss_desc' => 'സജീവ സംഭവങ്ങളുടെ എണ്ണം കാണിക്കുകയും ബാധിക്കപ്പെട്ട സേവനങ്ങൾ അവയുടെ ആഘാത നില ബാഡ്ജുകളോടെ (വലിയ തടസ്സം, ഭാഗിക തടസ്സം, മോശമായ പ്രകടനം, പരിപാലനം) പട്ടികപ്പെടുത്തുകയും ചെയ്യുന്നു. എല്ലാം ആരോഗ്യകരമാകുമ്പോൾ, ഒരു പച്ച "എല്ലാ സിസ്റ്റങ്ങളും പ്രവർത്തനക്ഷമം" ബാനർ പ്രത്യക്ഷപ്പെടുന്നു.',
        's4_ss_triggers' => '<strong>ചുവപ്പ്:</strong> ഏതെങ്കിലും സേവനത്തിൽ വലിയ അല്ലെങ്കിൽ ഭാഗിക തടസ്സം. <strong>മഞ്ഞ:</strong> മോശമായ പ്രകടനം അല്ലെങ്കിൽ പരിപാലന നില. <strong>പച്ച:</strong> എല്ലാ സിസ്റ്റങ്ങളും പ്രവർത്തനക്ഷമം.',
        's4_ct_title' => 'കരാറുകൾ',
        's4_ct_desc' => '30 ദിവസത്തിനുള്ളിൽ, 90 ദിവസത്തിനുള്ളിൽ കാലഹരണപ്പെടുന്ന കരാറുകളും അടുക്കുന്ന അറിയിപ്പ് കാലയളവുകളും പ്രദർശിപ്പിക്കുന്നു. ആസന്നമായ കാലഹരണങ്ങളെയും വരാനിരിക്കുന്ന അറിയിപ്പ് സമയപരിധികളെയും കുറിച്ച് ശ്രദ്ധാ ഇനങ്ങൾ മുന്നറിയിപ്പ് നൽകുന്നു.',
        's4_ct_triggers' => '<strong>ചുവപ്പ്:</strong> 30 ദിവസത്തിനുള്ളിൽ കാലഹരണപ്പെടുന്ന കരാറുകൾ. <strong>മഞ്ഞ:</strong> 90 ദിവസത്തിനുള്ളിൽ കാലഹരണപ്പെടുന്ന കരാറുകൾ അല്ലെങ്കിൽ അടുക്കുന്ന അറിയിപ്പ് കാലയളവുകൾ. <strong>പച്ച:</strong> ശ്രദ്ധ ആവശ്യമുള്ള കരാറുകളൊന്നുമില്ല.',
        's4_sw_title' => 'സോഫ്റ്റ്‌വെയർ',
        's4_sw_desc' => '30 ദിവസത്തിനുള്ളിൽ, 90 ദിവസത്തിനുള്ളിൽ പുതുക്കുന്ന സോഫ്റ്റ്‌വെയർ ലൈസൻസുകളും തീരുന്ന അറിയിപ്പ് കാലയളവുകളും കാണിക്കുന്നു. ലൈസൻസ് പുതുക്കൽ തീയതികൾ എപ്പോഴും രേഖയിലുണ്ടായിരുന്നു; അത് കാലഹരണപ്പെടുന്നതിന് മുമ്പ് ദൃശ്യമാക്കുന്നത് ഇതാണ്.',
        's4_sw_triggers' => '<strong>ചുവപ്പ്:</strong> 30 ദിവസത്തിനുള്ളിൽ പുതുക്കുന്ന ലൈസൻസുകൾ. <strong>മഞ്ഞ:</strong> 90 ദിവസത്തിനുള്ളിൽ പുതുക്കുന്ന ലൈസൻസുകൾ അല്ലെങ്കിൽ അടുക്കുന്ന അറിയിപ്പ് കാലയളവുകൾ. <strong>പച്ച:</strong> ശ്രദ്ധ ആവശ്യമായ സോഫ്റ്റ്‌വെയർ പുതുക്കലുകളൊന്നുമില്ല. പുതുക്കൽ തീയതികളൊന്നും രേഖപ്പെടുത്തിയിട്ടില്ലെങ്കിൽ, ശൂന്യമായ ലിസ്റ്റിൽ എല്ലാം ശരിയാണെന്ന് പറയുന്നതിന് പകരം കാർഡ് അത് വ്യക്തമായി പറയുന്നു.',
        's4_kb_title' => 'അറിവ്',
        's4_kb_desc' => 'അവലോകനത്തിന് കാലാവധി കഴിഞ്ഞ ലേഖനങ്ങളുടെ എണ്ണം കാണിക്കുകയും ഈ ആഴ്ച അടുത്തിടെ പ്രസിദ്ധീകരിച്ച ലേഖനങ്ങൾ പട്ടികപ്പെടുത്തുകയും ചെയ്യുന്നു. അവലോകനങ്ങളൊന്നും കാലഹരണപ്പെടാത്തപ്പോഴും നോളഡ്ജ് ബേസ് കാലികമാകുമ്പോഴും കാർഡ് എല്ലാം-വ്യക്തം സന്ദേശം കാണിക്കുന്നു.',
        's4_kb_triggers' => '<strong>മഞ്ഞ:</strong> അവലോകനത്തിന് കാലാവധി കഴിഞ്ഞ ലേഖനങ്ങൾ. <strong>പച്ച:</strong> നോളഡ്ജ് ബേസ് കാലികമാണ്.',
        's4_as_title' => 'ആസ്തികൾ',
        's4_as_desc' => 'ട്രാക്ക് ചെയ്യപ്പെട്ട ആസ്തികളുടെ മൊത്തം എണ്ണവും 7 അല്ലെങ്കിൽ അതിലധികം ദിവസമായി കണ്ടിട്ടില്ലാത്തവ എത്രയെന്നും പ്രദർശിപ്പിക്കുന്നു. ഓഫ്‌ലൈൻ ആയിരിക്കാവുന്ന, ഡീകമ്മീഷൻ ചെയ്ത, അല്ലെങ്കിൽ നഷ്ടപ്പെട്ട ഉപകരണങ്ങൾ തിരിച്ചറിയാൻ ഇത് സഹായിക്കുന്നു.',
        's4_as_triggers' => '<strong>മഞ്ഞ:</strong> 7+ ദിവസമായി കണ്ടിട്ടില്ലാത്ത ആസ്തികൾ. <strong>പച്ച:</strong> എല്ലാ ആസ്തികളും അടുത്തിടെ സജീവമായിരുന്നു.',
        's5_title' => 'സ്വയം പുതുക്കലും മാനുവൽ പുതുക്കലും',
        's5_intro' => 'ദിവസം മുഴുവൻ ഒരു ബ്രൗസർ ടാബിൽ തുറന്നുവെക്കാവുന്ന ഒരു നിഷ്ക്രിയ നിരീക്ഷണ ഉപകരണമായാണ് വാച്ച്‌ടവർ രൂപകൽപ്പന ചെയ്തിരിക്കുന്നത്. സ്വയം പുതുക്കൽ ചക്രങ്ങളിലൂടെ ഡാഷ്‌ബോർഡ് സ്വയം കാലികമായി നിലനിർത്തുന്നു.',
        's5_step1' => '<strong>സ്വയം പുതുക്കൽ</strong> &mdash; ഡാഷ്‌ബോർഡ് ഓരോ 5 മിനിറ്റിലും എല്ലാ മൊഡ്യൂളുകളിൽ നിന്നും പുതിയ ഡാറ്റ എടുക്കുന്നു. പേജ് റീലോഡ് ചെയ്യുകയോ ഒന്നും ക്ലിക്ക് ചെയ്യുകയോ വേണ്ട; കാർഡുകളും സ്റ്റാറ്റസ് ഡോട്ടുകളും പശ്ചാത്തലത്തിൽ നിശ്ശബ്ദമായി പുതുക്കുന്നു.',
        's5_step2' => '<strong>മാനുവൽ പുതുക്കൽ</strong> &mdash; ഏറ്റവും പുതിയ ഡാറ്റ ഉടനടി എടുക്കാൻ മുകളിൽ-വലത് കോണിലെ <strong>പുതുക്കുക</strong> ബട്ടൺ ക്ലിക്ക് ചെയ്യുക. അഭ്യർത്ഥന പുരോഗമിക്കുമ്പോൾ ബട്ടൺ ഐക്കൺ കറങ്ങുന്നു, പുതിയ ഡാറ്റ ലോഡ് ചെയ്യപ്പെടുന്നുവെന്ന് സ്ഥിരീകരിക്കുന്നു.',
        's5_step3' => '<strong>പുതുക്കിയ ടൈംസ്റ്റാമ്പ്</strong> &mdash; പുതുക്കൽ ബട്ടണിന് അടുത്തായി, ഡാറ്റ അവസാനമായി എടുത്ത സമയം ഒരു ടൈംസ്റ്റാമ്പ് കാണിക്കുന്നു (ഉദാ. "പുതുക്കി 09:15"). പ്രദർശിപ്പിച്ച വിവരം എത്രമാത്രം കാലികമാണെന്ന് ഇത് കൃത്യമായി പറയുന്നു.',
        's5_tip' => 'നിഷ്ക്രിയ നിരീക്ഷണത്തിനായി വാച്ച്‌ടവർ ഒരു സമർപ്പിത ബ്രൗസർ ടാബിൽ തുറന്നുവെക്കുക. 5 മിനിറ്റ് പുതുക്കൽ ചക്രം എന്നാൽ ഓരോ മൊഡ്യൂളും മാനുവലായി പരിശോധിക്കാതെ തന്നെ നിങ്ങളുടെ IT പ്രവർത്തനങ്ങളുടെ ഏതാണ്ട്-തത്സമയ കാഴ്ച എപ്പോഴും നിങ്ങൾക്കുണ്ടെന്നാണ്.',
        's6_title' => 'ദ്രുത നുറുങ്ങുകൾ',
        's6_tip1_title' => 'നിങ്ങളുടെ ദിവസം ഇവിടെ ആരംഭിക്കുക',
        's6_tip1_desc' => 'ഒരു ദ്രുത പ്രവർത്തന അവലോകനത്തിനായി ഓരോ പ്രഭാതത്തിലും ആദ്യം വാച്ച്‌ടവർ തുറക്കുക. നിമിഷങ്ങൾക്കുള്ളിൽ പ്രഭാത പരിശോധനകൾ പൂർത്തിയായോ, ഏതെങ്കിലും ടിക്കറ്റുകൾ അടിയന്തരമാണോ, എല്ലാ സേവനങ്ങളും ആരോഗ്യകരമാണോ എന്നൊക്കെ കാണാം.',
        's6_tip2_title' => 'ചുവപ്പ് ഡോട്ടുകൾ ആദ്യം',
        's6_tip2_desc' => 'മറ്റെന്തിനെക്കാളും മുമ്പ് ചുവപ്പ് സ്റ്റാറ്റസ് ഡോട്ടുകൾ പരിഹരിക്കുക. ഉടനടി ശ്രദ്ധ ആവശ്യമുള്ള അടിയന്തര ഇനങ്ങളെ ഇവ സൂചിപ്പിക്കുന്നു &mdash; പരാജയപ്പെട്ട പരിശോധനകൾ, ഉയർന്ന മുൻഗണനയുള്ള ടിക്കറ്റുകൾ, അല്ലെങ്കിൽ ഉപയോക്താക്കളെ സജീവമായി ബാധിക്കുന്ന സേവന തടസ്സങ്ങൾ.',
        's6_tip3_title' => 'കടക്കാൻ ക്ലിക്ക് ചെയ്യുക',
        's6_tip3_desc' => 'ആ മൊഡ്യൂളിലേക്ക് നേരെ നാവിഗേറ്റ് ചെയ്യാൻ ഒരു കാർഡിലെ ഏത് മൊഡ്യൂൾ പേരും ക്ലിക്ക് ചെയ്യുക. പ്രധാന മെനുവോ വാഫിൾ നാവിഗേഷനോ ഉപയോഗിക്കേണ്ടതില്ല &mdash; ശ്രദ്ധ ആവശ്യമുള്ളിടത്തേക്ക് ഒരു നേരിട്ടുള്ള കുറുക്കുവഴിയായി വാച്ച്‌ടവർ പ്രവർത്തിക്കുന്നു.',
        's6_tip4_title' => 'ഏറ്റവും പുതിയതിന് പുതുക്കുക അമർത്തുക',
        's6_tip4_desc' => 'ഡാഷ്‌ബോർഡ് ഓരോ 5 മിനിറ്റിലും സ്വയം പുതുക്കുമെങ്കിലും, ഏറ്റവും പുതിയ ഡാറ്റ വേണ്ടപ്പോഴെല്ലാം പുതുക്കുക ബട്ടൺ ക്ലിക്ക് ചെയ്യാം. ഒരു പ്രശ്നം പരിഹരിച്ച ശേഷം സ്റ്റാറ്റസ് ഡോട്ട് മാറിയോ എന്ന് സ്ഥിരീകരിക്കാൻ ഉപയോഗപ്രദമാണ്.',
        's6_tip5_title' => 'ടീം മീറ്റിംഗുകളിൽ ഇത് ഉപയോഗിക്കുക',
        's6_tip5_desc' => 'സ്റ്റാൻഡ്-അപ്പുകളിലോ പ്രവർത്തന അവലോകന മീറ്റിംഗുകളിലോ വാച്ച്‌ടവർ ഒരു സ്ക്രീനിലേക്ക് പ്രൊജക്റ്റ് ചെയ്യുക. ഏതൊക്കെ മേഖലകൾക്ക് ശ്രദ്ധ വേണമെന്ന് ചർച്ച ചെയ്യാനും മഞ്ഞ അല്ലെങ്കിൽ ചുവപ്പ് ഇനങ്ങളുടെ ഉത്തരവാദിത്തം ഏൽപ്പിക്കാനും നിറം-കോഡ് ചെയ്ത ഡോട്ടുകൾ എളുപ്പമാക്കുന്നു.',
        's6_tip6_title' => 'പച്ച എന്നാൽ എല്ലാം വ്യക്തം',
        's6_tip6_desc' => 'ഡാഷ്‌ബോർഡിലെ എല്ലാ ഡോട്ടും പച്ചയാകുമ്പോൾ, നിങ്ങളുടെ IT പ്രവർത്തനങ്ങൾ നല്ല നിലയിലാണ്. അടിയന്തര ടിക്കറ്റുകളില്ല, പരാജയപ്പെട്ട പരിശോധനകളില്ല, കാലഹരണപ്പെടുന്ന കരാറുകളില്ല, എല്ലാ സേവനങ്ങളും പ്രവർത്തനക്ഷമം. അതാണ് ലക്ഷ്യം.',
        's7_title' => 'ക്രമീകരണങ്ങൾ',
        's7_intro' => 'Watchtower → Settings ഏതൊക്കെ കാർഡുകൾ കാണിക്കും, ഓരോ കണക്കും എന്താണ് എണ്ണുന്നത് എന്ന് തീരുമാനിക്കുന്നു. അവിടെയുള്ളതെല്ലാം ഇതിനകം ശരിയായ ഒരു ഡാഷ്‌ബോർഡിനെ വെട്ടിച്ചുരുക്കുന്നു: മുഴുവൻ സ്ക്രീനും തൊടാതെ വിട്ടാൽ എല്ലാ കാർഡും വരയ്ക്കുകയും എല്ലാ നിലയും കണക്കാക്കുകയും ചെയ്യും, അതിനാൽ കണക്കുകൾ ശരിയാകാൻ ഒന്നും കോൺഫിഗർ ചെയ്യേണ്ടതില്ല.',
        's7_cards_title' => 'കാർഡുകൾ',
        's7_cards_desc' => 'നിങ്ങളുടെ ടീം ശ്രദ്ധിക്കാത്ത പത്ത് കാർഡുകളിൽ ഏതെങ്കിലും ഓഫ് ചെയ്യുക. ഒന്നും നഷ്ടപ്പെടില്ല — ഓരോ മൊഡ്യൂളും അതിന്റെ സ്വന്തം സ്ക്രീനുകളിൽ എല്ലാം കാണിക്കുന്നത് തുടരും.',
        's7_counts_title' => 'കൗണ്ടുകൾ',
        's7_counts_desc' => 'ഓരോ കൗണ്ടിലും നിങ്ങൾക്കുള്ള എല്ലാ നിലയും ഉൾപ്പെടുന്നു, അതുകൊണ്ടാണ് ഒന്ന് പേര് മാറ്റുന്നതോ ചേർക്കുന്നതോ എവിടെയും ലിസ്റ്റ് ചെയ്യാതെ തന്നെ പ്രവർത്തിക്കുന്നത്. ഒറ്റനോട്ടത്തിൽ വായിക്കാൻ ആഗ്രഹിക്കുന്നതിലും കൂടുതൽ ഒരു കാർഡ് കാണിക്കുന്നുവെങ്കിൽ മാത്രം ഒന്ന് ചുരുക്കുക. ഓരോ വരിയും അത് ബാധിക്കുന്ന മൊഡ്യൂളിന്റെ നിറത്തിൽ, ആ മൊഡ്യൂൾ ടാഗ് ചെയ്തിരിക്കുന്നു.',
        's7_mc_title' => 'ഏതൊക്കെ മോർണിംഗ് ചെക്കുകൾ ഒരു പ്രശ്നമായി കണക്കാക്കും',
        's7_mc_desc' => 'നിങ്ങളുടെ മോർണിംഗ്-ചെക്ക് നിലകളിൽ ഏതാണ് പാസ്സ്, ഏതാണ് പരാജയം എന്ന് FreeITSM-ൽ ഒന്നും രേഖപ്പെടുത്തുന്നില്ല — അവ നിങ്ങളുടെ ലേബലുകളാണ്. നിങ്ങൾ പറയുന്നതുവരെ, കാർഡ് നിങ്ങളുടെ സ്വന്തം ക്രമത്തിലെ ആദ്യത്തെ നില മാത്രം നല്ലതായി കണക്കാക്കും, ചെക്കുകൾ പാസ്സായി എന്നതിന് പകരം പൂർത്തിയായി എന്ന് റിപ്പോർട്ട് ചെയ്യും. കുഴപ്പം അർത്ഥമാക്കുന്നവയ്ക്ക് പേര് നൽകിയാൽ അത് പകരം ഉപയോഗിക്കും.',
        's7_red_title' => 'ഏതൊക്കെ സേവന പ്രശ്നങ്ങൾ ലൈറ്റ് ചുവപ്പാക്കും',
        's7_red_desc' => 'ഓരോ ആഘാത നിലവാരത്തിന്റെയും "counts as downtime" ക്രമീകരണത്തിൽ നിന്ന് മനഃപൂർവ്വം വേറെ തിരഞ്ഞെടുത്തിരിക്കുന്നു: അത് നിങ്ങളുടെ അപ്ടൈം ശതമാനങ്ങൾ തീരുമാനിക്കുന്നു, അതിനാൽ ഇവിടെ ഒരു നിറം മാറ്റാൻ നിങ്ങളുടെ റിപ്പോർട്ടിംഗ് ഒരിക്കലും വളച്ചൊടിക്കേണ്ടതില്ല. തൊടാതെ വിട്ടാൽ ഇത് ആ നിലവാരങ്ങളെ പിന്തുടരും, അതിനാൽ നിങ്ങൾ മറ്റൊന്ന് പറയുന്നതുവരെ ഒന്നും മാറില്ല.',
        's7_paused_title' => 'വളരെ നേരം താൽക്കാലികമായി നിർത്തി',
        's7_paused_desc' => 'Watchtower ഇത് പരാമർശിക്കുന്നതിന് മുമ്പ് SLA ക്ലോക്ക് നിർത്തിയ നിലയിൽ ഒരു ടിക്കറ്റിന് എത്ര മണിക്കൂർ ഇരിക്കാം. സ്ഥിരസ്ഥിതി 24 ആണ്.',
    ],
